_czmbWide = new function() {

	this.anim;
	this.bottomText;
	this.bottomLoop;
	this.player;
	this.banner;
	this.cztk;
	this.click_url;
	this.clickThrottle;


	this.start = function() {		
		czQuery("head").append("<style type='text/css'>" + _czmbConfig.css + "</style>");

		this.anim = new TimelineMax();
		this.bottomText = new TimelineMax();
		this.bottomLoop = new TimelineMax();
		this.homeScene = new TimelineMax();
		this.scene1 = new TimelineMax();
		this.scene2 = new TimelineMax();
		this.scenes = [this.homeScene,this.scene1, this.scene2];
		this.canIChangeScene = true;
		this.currentScene = this.homeScene;
		this.currentSceneIndex = 0;

		this.clickThrottle = false;
		this.cztk = _czmb.getCpnI(_czmbConfig.bannerType, 'tid');
		this.click_url = _czmb.getCpnI(1, "ucl").replace("[timestamp]", _czmb.gtt());
		this.banner = _czmbWide.createBanner();

		var app =
			"<div id='czmb-b'><div id='czmb-expansion-load'></div></div>" +
			"<div id='czmb-t'>" + 
				"<div id='czmb-t-video1-mask'>" +  
					"<div id='czmb-t-video1'></div>" + 
				"</div>" +
				"<div id='czmb-t-video2-mask'>" +  
					"<div id='czmb-t-video2'></div>" + 
				"</div>" +
			"</div>";
		this.banner.append(app);
		this.banner.append('<img id="czmb-t-close" src="data:image/svg+xml;base64,">');

		/* Preparando Vídeo */
		this.videoReady = false;
		this.lowReady = false;
		this.lowReady = false;
	   _czmbWide.player1 = new _czmb.video({
		   id : "EDxZXObjMPc",
		   div : "czmb-t-video1",
		   height: '100%',
		   width: '100%',
		   onStart: function(){
			   _czmbWide.videoReady = true;
			   if (_czmbWide.lowReady) _czmbWide.go();
		   }
	   });
	   _czmbWide.player2 = new _czmb.video({
		   id : "hmTn4wiTthQ",
		   div : "czmb-t-video2",
		   height: '100%',
		   width: '100%',
	   });

		_czmb.loadImage(_czmbConfig.img_path+"bottom", _czmbConfig.bot_images, "czmb-b", 'czmb-b-', 'png', function(){
			_czmbWide.go();
		});
		_czmb.loadImage(_czmbConfig.img_path+"top", _czmbConfig.top_images, "czmb-t", 'czmb-t-');

	};

	this.go = function(){
		_czmb.pushTrack(_czmbWide.cztk, 'print');
		var cztk = window._czmb.getCpnI(_czmbConfig.bannerType, 'tid');
        if (window._czmb.hasOwnProperty("checkViewability")) {
            window._czmb.checkViewability("#czmb-wide", cztk);
        }
		_czmbWide.banner.removeAttr("style");
		czQuery("#czmb-b").click(function() {
			_czmbWide.click();
			_czmbWide.banner.unbind("mouseleave");
			_czmbWide.banner.mouseenter();
		});
		czQuery("#czmb-t-close").click(function() {
			_czmbWide.close();
		});
		czQuery("#czmb-t").children().click(function(e) {
			_czmbWide.click(e);
		});
		_czmbWide.actions();
		_czmbWide.animations();
		_czmbWide.banner.show();
	};

	this.close = function() {
		this.anim.pause(0.5);
		this.bottomText.play();
		this.bottomLoop.play();
		TweenMax.to("#czmb-b", .1, {autoAlpha:1})
		this.resetBanner();
		
		// _czmbWide.sendExpansionTimeEvent();
		czQuery("#czmb-t-close").animate({
			bottom: -100,
			autoAlpha: 0
		});
		czQuery("#czmb-b").animate({
			right: "110%"
		}, 500);

		_czmbWide.actions();
		_czmbWide.anim.pause(0);
		TweenMax.set("#czmb-t", {
			autoAlpha: 0
		});

		czQuery("#cz-overlay").fadeOut().remove();
	};

	this.click = function(e) {
		if (_czmbWide.clickThrottle === true){
			return false;
		}	
		_czmbWide.clickThrottle = true;
		
		this.banner.mouseleave();
		this.banner.unbind("mouseenter");
		this.banner.unbind("mouseleave");

		_czmb.pushTrack(this.cztk, "click");
		window.open(_czmbWide.click_url);
		setTimeout(function() {
			_czmbWide.close();
			_czmbWide.clickThrottle = false;
		}, 800);
	};

	this.createBanner = function() {
		if (_czmbConfig.bannerType == 1) type = "czmb-wide";
		czQuery("body").append("<div id=" + type + " style='bottom:-500px'></div>");
		var banner = czQuery("#" + type);
		if (_czmb.getCpnI(1, 'upr') != "") {
			banner.append('<img src="' + _czmb.getCpnI(1, 'upr').replace('[timestamp]', _czmb.gtt()) + '" width="1" height="1" border="0" alt="" />');
		}
		banner.hide();
		return banner;
	}

	this.actions = function() {
		this.banner.unbind("mouseenter");
		this.banner.unbind("mouseleave");

		this.banner.mouseenter(function() {
			czQuery("#czmb-expansion-load").stop().animate({
				width: "100%"
			}, 800, function() {
				_czmbWide.banner.unbind("mouseenter");
				_czmbWide.banner.unbind("mouseleave");
				_czmbWide.playBanner();
				_czmbWide.bottomText.pause();
				_czmbWide.bottomLoop.pause();
				TweenMax.to("#czmb-b", .1, {autoAlpha:0})
				_czmb.pushTrack(_czmbWide.cztk, 'interaction');
				czQuery("#czmb-expansion-load").animate({
					width: "0%"
				}, 800);
				czQuery("body").append("<div id='cz-overlay'></div>");
				TweenMax.set("#cz-overlay", {
					autoAlpha: 0,
					position: "fixed",
					zIndex: 2147483640,
					width: "100%",
					height: "100%",
					backgroundColor: "black",
					top: 0,
					left: 0
				});
				czQuery("#cz-overlay").click(function() {
					_czmbWide.close();
				});
				TweenMax.to("#cz-overlay", 0.5, {
					autoAlpha: 0.5
				});
			});
		});

		this.banner.mouseleave(function() {
			czQuery("#czmb-expansion-load").stop().animate({
				width: "0%"
			}, 500);
		});
	};

	this.playBanner = function() {
		czQuery("#czmb-b").fadeIn();
		if (_czmb.getCpnI(1, 'uin') != "") {
			_czmbWide.banner.append('<img src="' + _czmb.getCpnI(1, 'uin').replace('[timestamp]', _czmb.gtt()) + '" width="1" height="1" border="0" alt="" />');
		}
		this.anim.play();
		czQuery("#czmb-t-close").animate({
			bottom: 575,
			opacity: 1
		});
	};

	this.animations = function() {
		var bottom = {
			"background": new TimelineMax(),
			"text": new TimelineMax()
		};
		
		bottom.background
			.from('#czmb-b-bg', .7, {autoAlpha: 0, y: 100}, "start")
			.from("#czmb-b-logo", .7, {autoAlpha:0, scale:0.9, ease:Back.easeOut}, "start+=.5")
			.add(function(){
				_czmbWide.bottomLoop.play();
			}, "start+=.5")
			.from("#czmb-b-logo2", .7, {autoAlpha:0, scale:0.9, ease:Back.easeOut}, "start+=.7")
			.add(function(){
				_czmbWide.bottomText.play();
			}, "start+=1");

		_czmbWide.bottomText.pause(0);
		_czmbWide.bottomText.addLabel("start")
		.addLabel("start")
			.from("#czmb-b-t1", .7, {autoAlpha:0, y:-20, ease:Power3.easeOut}, "start")
			.to("#czmb-b-t1", .7, {autoAlpha:0, y:20, ease:Power3.easeIn}, "+=2.7")

			.from("#czmb-b-t2", .7, {autoAlpha:0, y:-20, ease:Power3.easeOut},"-=.2")
			.to("#czmb-b-t2", .7, {autoAlpha:0, y:20, ease:Power3.easeIn}, "+=2.7")

			.from("#czmb-b-t3", .7, {autoAlpha:0, y:-20, ease:Power3.easeOut},"-=.2")
			.to("#czmb-b-t3", .7, {autoAlpha:0, y:20, ease:Power3.easeIn}, "+=2.7")

			.from("#czmb-b-t4", .7, {autoAlpha:0, y:-20, ease:Power3.easeOut},"-=.2")
			.to("#czmb-b-t4", .7, {autoAlpha:0, y:20, ease:Power3.easeIn}, "+=2.7")

			.repeat(-1)

		_czmbWide.bottomLoop.pause(0);
		_czmbWide.bottomLoop.addLabel("start")
		.addLabel("start")
			.from("#czmb-b-e1", .7, {autoAlpha:0, rotationZ:30, ease:Power1.easeOut}, "start")
			.to("#czmb-b-e1", .7, {autoAlpha:0, rotationZ:-30, ease:Power1.easeIn}, "+=3")

			.from("#czmb-b-e2", .7, {autoAlpha:0, rotationZ:30, ease:Power1.easeOut}, "-=.2")
			.to("#czmb-b-e2", .7, {autoAlpha:0, rotationZ:-30, ease:Power1.easeIn}, "+=3")
			.repeat(-1)	

		//TOP	
 		this.anim.pause(0);
		this.anim.addLabel("start")
			.set("#czmb-t-b-p1, #czmb-t-b-p2", {autoAlpha:0}, "start")
			.from("#czmb-t", .25, {autoAlpha:0, height:0}, "start")
			.from("#czmb-t-p1", .7, {autoAlpha:0, x:-20, ease:Power3.easeOut}, "start")
			.from("#czmb-t-p2", .7, {autoAlpha:0, x:20, ease:Power3.easeOut}, "start")
			.from("#czmb-t-bg", .7, {autoAlpha:0}, "start+=1.4")
			.add(function() {
				_czmbWide.homeScene.play();
			}, "start+=1.8")
			.from("#czmb-t-logo", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=2")
			.from("#czmb-t-hotd", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=2.2")
			.add(()=>{
				_czmbWide.buttonActions();
			}, "start+=3")
			
		
		//--------------HOMEScene------------------
		this.homeScene.pause(0);
		this.homeScene.addLabel("start")
			.staggerFrom(["#czmb-t-t1", "#czmb-t-t2", "#czmb-t-t3"], .7, {autoAlpha:0, y:-20, ease:Back.easeOut},.1, "start")
			.to("#czmb-t-hotd", .5, {left:"343px", bottom:"438px", width:"308px", height:"149px"}, "start+=.7")
		this.homeScene.addLabel("pause")
		this.homeScene.addPause("pause")
		this.homeScene.addLabel("end")
			.staggerTo(["#czmb-t-t1", "#czmb-t-t2", "#czmb-t-t3"], .7, {autoAlpha:0, y:-20, ease:Back.easeOut}, "end")
		
		
		//-----------------SCENE1--------------------
		this.scene1.pause(0);
		this.scene1.addLabel("start")
			// #czmb-t-hotd-pos2{position:absolute;left:424px;bottom:501px;width:152px;height:72px;z-index:44}
			.to("#czmb-t-hotd", .5, {left:"424px", bottom:"501px", width:"152px", height:"72px"}, "start")
			.from("#czmb-t-v-bg", .7, {autoAlpha: 0}, "start")
			.staggerFrom(["#czmb-t-v-ttl", "#czmb-t-v-t1", "#czmb-t-v-t2"], .7, {autoAlpha:0, y:-10, ease:Back.easeOut}, .1, "start+=.4")
			.staggerFrom(["#czmb-t-v-p1", "#czmb-t-v-p2", "#czmb-t-v-p3", "#czmb-t-v-p4", "#czmb-t-v-p5"], .7, {autoAlpha:0, x:-10, ease:Power3.easeOut}, .1, "start+=.7")
			.staggerFrom(["#czmb-t-v-n1", "#czmb-t-v-n2", "#czmb-t-v-n3", "#czmb-t-v-n4", "#czmb-t-v-n5"], .7, {autoAlpha:0, y:10, ease:Power3.easeOut}, .1, "start+=.8")
			.from("#czmb-t-video1-bg", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=1.2")
			.from("#czmb-t-video1-mask", .7, {autoAlpha:0}, "start+=1.6")
			.from("#czmb-t-v-t-cta", .7, {autoAlpha:0, y:10}, "start+=1.6")
			.add(function () {
				_czmbWide.player1.play();
			}, "start+=1.6")
			.from("#czmb-t-cta-pretos", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=1.8")
			.from("#czmb-t-v-cta", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=2");

		this.scene1.addLabel("pause")
		this.scene1.addLabel("end")
			.to("#czmb-t-hotd", .5, {left:"424px", bottom:"501px", width:"152px", height:"72px"}, "end")
			.add(function () {
				// _czmbWide.player1.stop();
			}, "end")
			.to("#czmb-t-video1-mask, #czmb-t-video1-bg, #czmb-t-v-cta, #czmb-t-cta-pretos, #czmb-t-v-cta, #czmb-t-v-t-cta", .5, {autoAlpha:0}, "end")
			.staggerTo(["#czmb-t-v-p1", "#czmb-t-v-p2", "#czmb-t-v-p3", "#czmb-t-v-p4", "#czmb-t-v-p5", "#czmb-t-v-n1", "#czmb-t-v-n2", "#czmb-t-v-n3", "#czmb-t-v-n4", "#czmb-t-v-n5"], .5, {autoAlpha:0, x:-10, ease:Power3.easeOut}, .1, "end+=.2")
			.staggerTo(["#czmb-t-v-ttl", "#czmb-t-v-t1", "#czmb-t-v-t2"], .5, {autoAlpha:0, y:-10, ease:Back.easeOut}, .1, "end+=.4")
			.to("#czmb-t-v-bg", .5, {autoAlpha: 0}, "end+=.6")
		this.scene1.addPause("pause")
		//-----------------SCENE2--------------------
		this.scene2.pause(0);
		this.scene2.addLabel("start")
			// #czmb-t-hotd-pos2{position:absolute;left:424px;bottom:501px;width:152px;height:72px;z-index:44}
			.to("#czmb-t-hotd", .5, {left:"424px", bottom:"501px", width:"152px", height:"72px"}, "start")
			.from("#czmb-t-p-bg", .7, {autoAlpha: 0}, "start")
			.staggerFrom(["#czmb-t-p-ttl", "#czmb-t-p-t1", "#czmb-t-p-t2"], .7, {autoAlpha:0, y:-10, ease:Back.easeOut}, .1, "start+=.4")
			.staggerFrom(["#czmb-t-p-p1", "#czmb-t-p-p2", "#czmb-t-p-p3", "#czmb-t-p-p4", "#czmb-t-p-p5"], .7, {autoAlpha:0, x:-10, ease:Power3.easeOut}, .1, "start+=.7")
			.staggerFrom(["#czmb-t-p-n1", "#czmb-t-p-n2", "#czmb-t-p-n3", "#czmb-t-p-n4", "#czmb-t-p-n5"], .7, {autoAlpha:0, y:10, ease:Power3.easeOut}, .1, "start+=.8")
			.from("#czmb-t-video2-bg", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=1.2")
			.from("#czmb-t-video2-mask", .7, {autoAlpha:0}, "start+=1.6")
			.from("#czmb-t-p-t-cta", .7, {autoAlpha:0, y:10}, "start+=1.6")
			.add(function () {
				_czmbWide.player2.play();
			}, "start+=1.6")
			.from("#czmb-t-cta-verdes", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=1.8")
			.from("#czmb-t-p-cta", .7, {autoAlpha:0, scale:1.1, ease:Back.easeOut}, "start+=2");

		this.scene2.addLabel("pause")
		this.scene2.addLabel("end")
			.to("#czmb-t-hotd", .5, {left:"424px", bottom:"501px", width:"152px", height:"72px"}, "end")
			.add(function () {
				// _czmbWide.player2.stop();
			}, "end")
			.to("#czmb-t-video2-mask, #czmb-t-video2-bg, #czmb-t-p-cta, #czmb-t-cta-verdes, #czmb-t-p-cta, #czmb-t-p-t-cta", .5, {autoAlpha:0}, "end")
			.staggerTo(["#czmb-t-p-p1", "#czmb-t-p-p2", "#czmb-t-p-p3", "#czmb-t-p-p4", "#czmb-t-p-p5", "#czmb-t-p-n1", "#czmb-t-p-n2", "#czmb-t-p-n3", "#czmb-t-p-n4", "#czmb-t-p-n5"], .5, {autoAlpha:0, x:-10, ease:Power3.easeOut}, .1, "end+=.2")
			.staggerTo(["#czmb-t-p-ttl", "#czmb-t-p-t1", "#czmb-t-p-t2"], .5, {autoAlpha:0, y:-10, ease:Back.easeOut}, .1, "end+=.4")
			.to("#czmb-t-p-bg", .5, {autoAlpha: 0}, "end+=.6")
		this.scene2.addPause("pause")
			
		czQuery("#czmb-t-p1").unbind("mouseenter").mouseenter(()=>{
			TweenMax.to("#czmb-t-b-p1", .2, {autoAlpha:1})
		}).unbind("mouseleave").mouseleave(()=>{
			TweenMax.to("#czmb-t-b-p1", .2, {autoAlpha:0})
		})

		czQuery("#czmb-t-p2").unbind("mouseenter").mouseenter(()=>{
			TweenMax.to("#czmb-t-b-p2", .2, {autoAlpha:1})
		}).unbind("mouseleave").mouseleave(()=>{
			TweenMax.to("#czmb-t-b-p2", .2, {autoAlpha:0})
		})
		czQuery("#czmb-t-p-cta").unbind("click").click(()=>{
			window.open("https://www.hbomax.com/br/pt/shows/house-of-the-dragon/black-team", "_blank");
			_czmbWide.close();
		})

		czQuery("#czmb-t-v-cta").unbind("click").click(()=>{
			window.open("https://www.hbomax.com/br/pt/shows/house-of-the-dragon/green-team", "_blank");
			_czmbWide.close();
		})
	};

	this.buttonActions = function () {
		var menu = ["", "#czmb-t-p1, #czmb-t-cta-verdes", "#czmb-t-p2, #czmb-t-cta-pretos"];
		czQuery.each(menu, function (index, element) {
			czQuery(element)
				.unbind("click")
				.click(function (event) {
					event.preventDefault();
					event.stopPropagation();
					if (_czmbWide.currentSceneIndex != index && _czmbWide.canIChangeScene) {
						_czmbWide.toggleScenes(index);
						_czmbWide.currentSceneIndex = index;
						_czmbWide.canIChangeScene = false;
					}
				});	
		});
	}

	this.toggleScenes = function (givenIndex) {		
		var nextScene = _czmbWide.scenes[givenIndex];
		_czmbWide.currentScene.play("end");
		_czmbWide.player1.stop();
		_czmbWide.player2.stop();
		setTimeout(function () {
			nextScene.play("start");
			_czmbWide.currentScene = nextScene;
			_czmbWide.canIChangeScene = true;
		}, 1000);
		
	}

	this.resetBanner = function () {
		_czmbWide.player1.stop();
		_czmbWide.player2.stop();
		_czmbWide.canIChangeScene = true;
		_czmbWide.currentScene = _czmbWide.homeScene;
		_czmbWide.currentSceneIndex = 0;
		_czmbWide.resetScenes();
	}
	this.resetScenes = function () {
		_czmbWide.scenes.forEach(function (scene) {
			scene.pause(0);
		});
	}

}

/* . . . Aguardando o YouTubeIframeAPI ser totalmente carregado . . . */
if(typeof(YT) == 'undefined'){
	var youtube = document.createElement('script');
	youtube.src = "https://www.youtube.com/iframe_api";

	var firstScriptTag = document.getElementsByTagName('script')[0];
	firstScriptTag.parentNode.insertBefore(youtube, firstScriptTag);
	function onYouTubeIframeAPIReady() {
		_czmbWide.start();
		czQuery.ajaxSetup({
			cache: false
		});
	}
} else {
	_czmbWide.start();
	czQuery.ajaxSetup({
		cache: false
	});
}